/* Oaken Tower Fan Hub – item data (0-star base stats + ability text per star)
 * Source: oakentower.wiki.gg (Items table + Module:ItemData), CC BY-SA 4.0.
 * Row: I(name, rarity, "Pack|Pack2", tag, cost, "M"|"R", damage, cooldown, {stats}, [ability 0*,1*,2*,3*])
 * stats keys: crit(%), mc, poison, burn, bleed, shock, block(shield), heal, charges
 * ability: string = text, null = "no ability" at that star, array shorter than 4 = missing star reuses the last known text.
 * To add a new item just append one more I(...) line. The id is slug(name) and is part of saved builds – never rename.
 */
import type { ItemDef, ItemStats, Rarity } from '../core/types';
import { slug } from './slug';

const ITEMS: ItemDef[] = [];
function I(name: string, rarity: Rarity, packs: string, tag: string, cost: number, type: 'M' | 'R', dmg: number, cd: number, st: ItemStats, ab: (string | null)[]) {
  const p = packs.split('|');
  ITEMS.push({ id: slug(name), name, rarity, pack: p[0]!, pack2: p[1] || null, tag, cost, type, dmg, cd, st: st || {}, ab: ab || [] });
}
